#!/usr/bin/env node
// Generates the app's and the diagram page's colours from design/tokens.json:
// macos/Sources/FolioKit/Tokens.swift and frontend/src/tokens.ts.
// Usage: node scripts/tokens.mjs [--check]   (--check fails when a generated file is out of date)
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = join(dirname(fileURLToPath(import.meta.url)), '..')
const source = JSON.parse(readFileSync(join(repo, 'design/tokens.json'), 'utf8'))
const header = '// Generated by scripts/tokens.mjs from design/tokens.json; do not edit.'

// The `color` group as a flat list: { name, description, light, dark }. A token with light and dark
// children follows the appearance; any other token is the same in both. A group's description goes
// on its first token.
function collect(group, path, inherited, out) {
  for (const [key, node] of Object.entries(group)) {
    if (key.startsWith('$')) continue
    const name = [...path, key].map((part, i) => (i ? part[0].toUpperCase() + part.slice(1) : part)).join('')
    const description = node.$description ?? inherited
    inherited = undefined
    if (node.$value) {
      out.push({ name, description, light: node.$value, dark: node.$value })
    } else if (node.light?.$value && node.dark?.$value) {
      out.push({ name, description, light: node.light.$value, dark: node.dark.$value })
    } else {
      collect(node, [...path, key], description, out)
    }
  }
  return out
}
const tokens = collect(source.color, [], undefined, [])

const swiftHex = value => `0x${value.slice(1).toUpperCase()}`
const swift = `${header}
import AppKit

/// Folio's own colours (design/tokens.json). Chrome follows the system and uses system colours instead.
public enum Tokens {
${tokens.map(t => `${t.description ? `    /// ${t.description}\n` : ''}    public static let ${t.name} = ${
  t.light === t.dark ? `color(${swiftHex(t.light)})` : `pair(${swiftHex(t.light)}, ${swiftHex(t.dark)})`}`).join('\n')}

    private static func color(_ hex: UInt32) -> NSColor {
        NSColor(srgbRed: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255, blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    }

    private static func pair(_ light: UInt32, _ dark: UInt32) -> NSColor {
        NSColor(name: nil) { appearance in
            appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua ? color(dark) : color(light)
        }
    }
}
`

const ts = `${header}
// Folio's own colours, for the light and the dark look.
${['light', 'dark'].map(mode => `export const ${mode} = {
${tokens.map(t => `  ${t.name}: '${t[mode]}',`).join('\n')}
} as const
`).join('\n')}`

const outputs = { 'macos/Sources/FolioKit/Tokens.swift': swift, 'frontend/src/tokens.ts': ts }
const check = process.argv.includes('--check')
let stale = false
for (const [path, text] of Object.entries(outputs)) {
  const file = join(repo, path)
  if (check) {
    let current = ''
    try { current = readFileSync(file, 'utf8').replace(/\r\n/g, '\n') } catch {}
    if (current !== text) { console.error(`${path} is out of date: run node scripts/tokens.mjs`); stale = true }
  } else {
    writeFileSync(file, text)
  }
}
process.exit(stale ? 1 : 0)
